// Package list provides a scrolling list of rows, from the mygo List
// widget. The list builds only the rows in view and keeps its place
// among them; choosing a row highlights it in the accent color.
package list

import (
	"github.com/egoist/mygo/ui"
)

// Props configure the list.
type Props struct {
	// State is the place and the choice of the list, kept from frame
	// to frame. Give each list a state of its own, and set its fields
	// before building: to let the user choose a row, set
	// State.Selected = &app.Chosen, where app.Chosen is the row
	// chosen, -1 for none.
	State *ui.ListState
	// Items are the rows, each shown as its text, unless Row draws it.
	// Items also count the rows, so a Row builder changes only the
	// look, not the number.
	Items []string
	// Row draws row i in place of its text; nil shows Items[i] in a
	// line of the theme's height.
	Row func(c *ui.Context, i int)
	// OnChoose runs when the user chooses a row: i is the row chosen.
	// It needs State.Selected, which names the choice.
	OnChoose func(i int)
	// Disabled keeps the list from choosing rows.
	Disabled bool
}

// List draws the items as a scrolling list. A click chooses a row, as
// the arrow keys and Home and End do while the list has the keyboard
// focus; a double click or Enter submits it.
func List(c *ui.Context, p Props) *ui.Element {
	e := ui.List(c, p.State, len(p.Items), func(i int) {
		if p.Row != nil {
			p.Row(c, i)
			return
		}
		// The row shows its text across the list, as a row of the
		// gallery's lists does, so the chosen row highlights along the
		// whole list.
		ui.Row(c).Height(32).PaddingX(12).Children(func() {
			ui.Text(c, p.Items[i]).Grow(1)
		})
	})
	if p.OnChoose != nil && e.Changed() && p.State != nil && p.State.Selected != nil {
		p.OnChoose(*p.State.Selected)
	}
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package menu provides a shadcn/ui-style Menu: a button showing a label
// and an arrow, which opens a menu below it, as the pointer goes down on
// it, or for Enter, Space or Down while it has the focus. The menu holds
// the items of the Props, one above the other; choosing one runs its
// Action and closes the menu. An item may show a check and be disabled;
// a Separator item draws a line between the items.
//
//	menu.Menu(c, menu.Props{
//		Label: "File",
//		Items: []menu.Item{
//			{Label: "New", Action: func() { app.new() }},
//			{Separator: true},
//			{Label: "Save", Checked: app.dirty, Action: func() { app.save() }},
//		},
//	})
package menu

import "github.com/egoist/mygo/ui"

// Item is one entry of a Menu.
type Item struct {
	// Label is the text of the item.
	Label string
	// Checked shows a check beside the label, as for a setting that is
	// on.
	Checked bool
	// Disabled keeps the item from being chosen.
	Disabled bool
	// Separator draws a line instead of an item, as between groups of
	// items; the other fields are ignored.
	Separator bool
	// Action runs when the item is chosen; nil for none.
	Action func()
}

// Props describes the menu to draw.
type Props struct {
	// Label is the text of the button, such as "File".
	Label string
	// Items are the entries of the menu, in order.
	Items []Item
	// Disabled keeps the menu from opening.
	Disabled bool
}

// Menu draws the button, and the menu it opens, and returns the button,
// so a view can chain more calls on it.
func Menu(c *ui.Context, p Props) *ui.Element {
	e := ui.MenuButton(c, p.Label, func(m *ui.Menu) {
		for _, it := range p.Items {
			if it.Separator {
				m.Separator()
				continue
			}
			item := m.Item(it.Label)
			item.Checked(it.Checked).Disabled(it.Disabled)
			if item.Chosen() && it.Action != nil {
				it.Action()
			}
		}
	})
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package meter provides a shadcn/ui-style meter: a bar that shows a
// measure against its range, colored by how near the top it is, with a
// label and a live readout, from the Meter of MyGo.
//
//	meter.Meter(c, meter.Props{
//		Value:  0.78,
//		Max:    1,
//		Label:  "Disk usage",
//		Levels: &ui.MeterLevels{Warning: 0.7, Critical: 0.9},
//	})
package meter

import (
	"fmt"

	"github.com/egoist/mygo/ui"
)

// Props describes the meter to draw.
type Props struct {
	// Value is the measure, between Min and Max.
	Value float64
	// Min and Max bound the measure. A Max at or below Min is taken as 1
	// above Min, so a bare fraction fills the bar.
	Min, Max float64
	// Levels turn the bar the Warning color from its Warning share of the
	// range, and the Danger color from Critical. The zero value keeps the
	// Success color throughout. A Critical below Warning makes low values
	// the bad ones, as a battery's.
	Levels *ui.MeterLevels
	// Label is the text above the bar, next to the readout.
	Label string
	// Format renders the readout; the default prints the rounded value.
	Format func(v float64) string
}

// Meter draws the label, the readout and the bar, and returns the
// column. The readout follows the value as the app changes it, because
// the view builds every frame.
func Meter(c *ui.Context, p Props) *ui.Element {
	t := c.Theme()
	format := p.Format
	if format == nil {
		format = func(v float64) string { return fmt.Sprintf("%.0f", v) }
	}
	hi := p.Max
	if hi <= p.Min {
		hi = p.Min + 1
	}
	return ui.Column(c).Gap(t.Space(0.5)).Children(func() {
		if p.Label != "" {
			ui.Row(c).Gap(t.Space(2)).Children(func() {
				ui.Text(c, p.Label).FontSize(t.FontSize * 0.875).Bold().TextColor(t.TextMuted)
				ui.Text(c, format(p.Value)).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
			})
		}
		ui.Meter(c, p.Value, p.Min, hi, p.Levels).FillWidth()
	})
}

