// toolkit: a viewport to draw them in, and a way to push them.
//
//	toast.Viewport(c)   // once in the view
//	if b.Clicked() {
//		toast.Push(c, toast.Props{Title: "Saved", Type: toast.Success})
//	}
package toast

import (
	"time"

	"github.com/egoist/mygo/ui"
)

// Type names the kind of a toast, which the viewport colors.
type Type string

const (
	// Info is a neutral note, in the accent color.
	Info Type = "info"
	// Success is a good outcome, in the success color.
	Success Type = "success"
	// Warning is a caution, in the warning color.
	Warning Type = "warning"
	// Error is a failure, in the danger color.
	Error Type = "error"
)

// Props describes a toast to push.
type Props struct {
	// Title is the one-line summary.
	Title string
	// Description is the detail under it.
	Description string
	// Type colors the toast; Info when empty.
	Type Type
	// Action labels a button that runs OnAction, as "Undo".
	Action string
	// OnAction runs for the action button, which also closes the toast.
	OnAction func()
	// Timeout is how long the toast shows: 4 seconds when zero.
	Timeout time.Duration
}

// Push shows a toast of the given props, at the bottom right of the
// window.
func Push(c *ui.Context, p Props) {
	typ := p.Type
	if typ == "" {
		typ = Info
	}
	c.AddToast(ui.Toast{
		Title:       p.Title,
		Description: p.Description,
		Type:        string(typ),
		Action:      p.Action,
		OnAction:    p.OnAction,
		Timeout:     p.Timeout,
	})
}

// Viewport draws the toasts of the window, bottom right, styled by the
// theme. Call it once in the view, wherever; MyGo shows one viewport.
func Viewport(c *ui.Context) *ui.Element {
	t := c.Theme()
	return ui.ToastViewportBase(c, func(viewport *ui.Element, toasts []ui.Toast) {
		viewport.Padding(16).AlignItems(ui.End).Gap(t.Space(2))
		for _, ts := range toasts {
			tp := ui.ToastBase(c, ts)
			root := tp.Root
			root.Row().Gap(t.Space(3)).Padding(t.Space(2), t.Space(3)).Radius(t.Radius).
				Background(t.Background).Border(1, t.Border).MaxWidth(t.Space(72))
			root.Shadow(0, 6, 20, 0, ui.RGBA(0, 0, 0, 0.18))
			root.Children(func() {
				ui.Box(c).Size(t.Space(2.5), t.Space(2.5)).Radius(t.Space(1.25)).Background(toastColor(t, ts.Type)).Shrink(0)
				ui.Column(c).Gap(t.Space(0.5)).Grow(1).Children(func() {
					ui.Text(c, ts.Title).Bold().SingleLine()
					if ts.Description != "" {
						ui.Text(c, ts.Description).FontSize(t.FontSize * 0.875).TextColor(t.TextMuted)
					}
				})
				if ts.Action != "" {
					tp.ActionButton().Label(ts.Action).Children(func() { ui.Text(c, ts.Action).TextColor(t.Accent).Bold() })
				}
				tp.CloseButton().Label("Close").Children(func() { ui.Text(c, "✕").TextColor(t.TextMuted) })
			})
		}
	})
}

// toastColor returns the dot color of a toast type.
func toastColor(t *ui.Theme, typ string) ui.Color {
	switch typ {
	case "success":
		return t.Success
	case "warning":
		return t.Warning
	case "error":
		return t.Danger
	}
	return t.Accent
}

// Package toggle provides a shadcn/ui-style Toggle: a button that stays
// pressed while it is on, as Bold in an editor's toolbar, which a click
// or Space while it has the focus turns over.
//
//	toggle.Toggle(c, toggle.Props{On: &bold, Label: "B"})
package toggle

import "github.com/egoist/mygo/ui"

// Props describes the toggle to draw.
type Props struct {
	// On is whether the toggle is pressed.
	On *bool
	// Label is the text the toggle shows, such as "Bold".
	Label string
	// Disabled keeps the toggle from being pressed.
	Disabled bool
}

// Toggle draws a button that stays pressed while *On and returns it, so
// a view can chain more calls on it.
func Toggle(c *ui.Context, p Props) *ui.Element {
	e := ui.Toggle(c, p.On, p.Label)
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package togglegroup provides a shadcn/ui-style ToggleGroup: a row of
// toggle buttons drawn joined as the segments of one control, as Bold,
// Italic and Underline in an editor's toolbar. Each toggle keeps its own
// state, so several may be on at once; they are one stop of Tab, among
// which the arrows move the focus.
//
//	togglegroup.ToggleGroup(c, togglegroup.Props{
//		Items: []togglegroup.Item{
//			{On: &app.bold, Label: "B", Tip: "Bold"},
//			{On: &app.italic, Label: "I", Tip: "Italic"},
//		},
//	})
package togglegroup

import "github.com/egoist/mygo/ui"

// Item is one toggle of the group: a button that stays pressed while
// *On, showing Label.
type Item struct {
	// On is whether the toggle is pressed.
	On *bool
	// Label is the text the toggle shows, such as "B" for Bold.
	Label string
	// Tip is the tooltip of the toggle, shown as the pointer rests on
	// it; empty for none.
	Tip string
}

// Props describes the toggle group to draw.
type Props struct {
	// Items are the toggles of the group, in order.
	Items []Item
	// Disabled keeps the toggles from being pressed.
	Disabled bool
}

// ToggleGroup draws the toggles joined as one control and returns it, so
// a view can chain more calls on it.
func ToggleGroup(c *ui.Context, p Props) *ui.Element {
	e := ui.ToggleGroup(c, func() {
		for _, it := range p.Items {
			tg := ui.Toggle(c, it.On, it.Label)
			if it.Tip != "" {
				tg.Tooltip(it.Tip)
			}
		}
	})
	if p.Disabled {
		e.Disabled(true)
	}
	return e
}

// Package tokenfield provides a field of tokens, as of tags or the
// recipients of a mail, as a shadcn/ui component for the TokenField of
// MyGo: the tokens show as chips, each with a button taking it out, and
// typing adds one on Enter or a comma, the suggestions of what was typed
// showing below it, of those not already chips.
//
//	tokenfield.TokenField(c, tokenfield.Props{
//		Tokens:      &tags,
//		Suggestions: []string{"urgent", "later", "work"},
//		Label:       "Tags",
//	})
package tokenfield

import (
	"github.com/egoist/mygo/ui"
)

// Props describes the field to draw.
type Props struct {
	// Tokens are the chips of the field, which it changes in place.
	Tokens *[]string
	// Suggestions are the texts offered, of those containing the text
	// typed, and not already chips.
	Suggestions []string
	// Label names the field for the assistive technology.
	Label string
}

// TokenField draws the tokens as chips and the field adding them, and
// returns it, so a view can chain more calls on it. A chip has a button
// taking it out; typing adds a token on Enter or a comma, a suggestion
// adds on Enter or a click, and Backspace in the empty field takes out
// the last.
func TokenField(c *ui.Context, p Props) *ui.Element {
	e := ui.TokenField(c, p.Tokens, p.Suggestions)
	if p.Label != "" {
		e.Label(p.Label)
	}
	return e
}

// Package toolbar provides a row of actions along the top of a window,
// from the mygo Toolbar widget. The controls are one stop of Tab; those
// that do not fit go, from the last, into a menu at the end.
package toolbar

import (
	"github.com/egoist/mygo/ui"
)

// Props configure the toolbar.
type Props struct {
	// Label names the toolbar for assistive technology.
	Label string
	// Children builds the controls: buttons, toggles, toggle groups
	// and menu buttons, which take no face of their own until hovered.
	// A Spacer pushes the controls after it to the end.
	Children func(c *ui.Context)
	// Disabled disables the controls of the toolbar.
	Disabled bool
}

// Toolbar draws the controls in a row, one stop of Tab, with Left and
// Right moving the focus among them, and Home and End to the first and
// the last.
func Toolbar(c *ui.Context, p Props) *ui.Element {
	tb := ui.Toolbar(c, func() {
		if p.Children != nil {
			p.Children(c)
		}
	})
	if p.Label != "" {
		tb.Label(p.Label)
	}
	if p.Disabled {
		tb.Disabled(true)
	}
	return tb
}

// Package tooltip provides a shadcn/ui-style Tooltip: a hint that shows
// once the pointer has rested on the anchor for a moment, and goes as
// the pointer leaves it or presses it, and with Escape, until the pointer
// or the focus comes back. The anchor is any element a view has already
// built; Tooltip attaches the hint to it.
//
//	save := ui.Button(c, "Save")
//	tooltip.Tooltip(c, tooltip.Props{Anchor: save, Text: "Save the file"})
package tooltip

import "github.com/egoist/mygo/ui"

// Props describes the tooltip to draw.
type Props struct {
	// Anchor is the element the tip belongs to.
	Anchor *ui.Element
	// Text is what the tip says.
	Text string
	// Disabled keeps the tip away, even as the pointer rests.
	Disabled bool
}

// Tooltip attaches a hint to the anchor and returns it, so a view can
// chain more calls on it.
func Tooltip(c *ui.Context, p Props) *ui.Element {
	if p.Disabled {
		return p.Anchor
	}
	return p.Anchor.Tooltip(p.Text)
}

// Package tree provides a hierarchical list whose branches open and
// close, from the mygo Tree and TreeItem widgets. A node with Children
// is a branch, one without them a leaf. Choosing a node highlights it
// and runs its action.
package tree

import (
	"github.com/egoist/mygo/ui"
)

// Item is one node of the tree.
type Item struct {
	// Label is the text of the node. Labels must differ, as the chosen
	// node is found by its label.
	Label string
	// Open opens and closes a branch. A branch — an item with Children —
	// needs it; the tree flips it when the arrow is clicked.
	Open *bool
	// Children are the nodes inside the branch.
	Children []Item
	// Action runs when the node is chosen, by a click or Enter.
	Action func()
}

// Props configure the tree.
type Props struct {
	// Items are the nodes of the tree.
	Items []Item
	// Chosen is the label of the chosen node. The tree sets it when a
	// node is chosen and shows the node highlighted. nil keeps the tree
	// from highlighting.
	Chosen *string
	// Disabled keeps the tree from opening or choosing nodes.
	Disabled bool
}

// Tree draws the items as a tree. A click on the arrow of a branch
// opens or closes it; a click on a node, or Enter, chooses it. While a
// node has the keyboard focus, Up and Down move around it, Right opens
// it or moves to its first child, and Left closes it or moves to its
// parent.
func Tree(c *ui.Context, p Props) *ui.Element {
	t := ui.Tree(c, func() {
		for _, it := range p.Items {
			build(c, it, p)
		}
	})
	if p.Disabled {
		t.Disabled(true)
	}
	return t
}

// build draws a node, the nodes inside it, and applies the choice.
func build(c *ui.Context, it Item, p Props) {
	item := ui.TreeItem(c, it.Label, it.Open, func() {
		for _, child := range it.Children {
			build(c, child, p)
		}
	})
	if p.Chosen != nil {
		item.Selected(*p.Chosen == it.Label)
	}
	if item.Clicked() {
		if p.Chosen != nil {
			*p.Chosen = it.Label
		}
		if it.Action != nil {
			it.Action()
		}
	}
}
